"""python3 moc-tay.py → loi.js: mốc đầu câu canh tay (giây) theo cua-so.json + lưới nhịp 150 BPM (phách 0,4 giây), mốc lấy từ cua-so.json. Sửa số ở MOC rồi chạy lại."""
import json,re
MOC=[5.0,6.0,7.5,10.5,12.5,19.5,21.0,24.0,26.8,28.6,30.4,32.3,34.1,35.9,37.7,39.5,41.4,43.2,45.0,48.8,51.0,53.4,57.4,59.4,60.6,61.8,63.0,64.0,69.0,71.1,73.2,75.3,77.4,79.5,81.6,83.7,85.8,87.3,88.8,90.3,91.6,93.5,95.0,97.0,98.5,99.9,101.4,102.9,104.3,105.8,107.3,108.7,110.2,111.6,113.1,116.2,118.4,121.6,125.0,129.4,132.4,133.6,135.0,136.4,138.0,139.4,140.6,142.6,144.4,146.2,148.2,151.0,154.6,156.6,158.6,161.2,163.0,164.6,165.6,166.8,193.4,195.0,197.6,199.0,201.8,203.0,204.4,206.0,208.2,209.6,211.6,212.6,214.2,215.6,216.8,218.0,219.6,221.6,223.0,225.0,230.4,231.4,232.8,234.0,235.4,237.0,239.0,241.0,245.0,246.4,247.8,249.0,250.6,251.8,252.8,254.0,257.0,258.4,259.8,261.2,262.4,263.8,265.2,267.4,269.8,271.2,272.6,274.0,275.4,276.8,278.2,279.6,281.0,284.6,285.6,286.8,288.0,289.6,290.6,291.4,292.4,293.2,296.0,297.2,299.6,302.0,305.0,331.0,332.6]
cau=[];di=-1;nh=''
for d in open('loi.txt',encoding='utf-8'):
  d=d.strip()
  if not d: continue
  if d.startswith('['): nh=d.strip('[]').split('|')[-1].strip();di+=1;continue
  cau.append({'c':d,'g':nh.rstrip('*').strip(),'di':di,'lang':nh.endswith('*')})
assert len(cau)==len(MOC),(len(cau),len(MOC))
for i,x in enumerate(cau):
  x['a']=MOC[i];sau=MOC[i+1] if i+1<len(MOC) else x['a']+4
  x['b']=round(min(sau-.1,x['a']+(6 if x['lang'] else 4.2)),2)
open('loi.js','w',encoding='utf-8').write('/* tạo bằng moc-tay.py – mốc a (giây) canh tay */\nwindow.TONG_NHAC=336.4;\nwindow.LOI_T='+json.dumps(cau,ensure_ascii=False)+';\n')
print(len(cau),'câu')
